import{_ as a,o as l,c as i,ag as t}from"./chunks/framework.BYYsWsaA.js";const p=JSON.parse('{"title":"AI 设置页测试功能说明","description":"","frontmatter":{},"headers":[],"relativePath":"ai-settings-test.md","filePath":"ai-settings-test.md","lastUpdated":1773599229000}'),o={name:"ai-settings-test.md"};function d(r,e,c,n,h,s){return l(),i("div",null,[...e[0]||(e[0]=[t('<h1 id="ai-设置页测试功能说明" tabindex="-1">AI 设置页测试功能说明 <a class="header-anchor" href="#ai-设置页测试功能说明" aria-label="Permalink to &quot;AI 设置页测试功能说明&quot;">​</a></h1><h2 id="页面" tabindex="-1">页面 <a class="header-anchor" href="#页面" aria-label="Permalink to &quot;页面&quot;">​</a></h2><ul><li><code>http://localhost:5173/ai-settings</code></li></ul><h2 id="新增能力" tabindex="-1">新增能力 <a class="header-anchor" href="#新增能力" aria-label="Permalink to &quot;新增能力&quot;">​</a></h2><p>AI 设置页现在支持“测试可用性”按钮。</p><p>这个按钮不是前端本地假检查，而是会把当前表单中的配置直接发送给后端测试接口，由后端按真实逻辑执行一次测试。</p><h2 id="后端接口" tabindex="-1">后端接口 <a class="header-anchor" href="#后端接口" aria-label="Permalink to &quot;后端接口&quot;">​</a></h2><ul><li><code>POST /api/v1/ai/settings/test</code></li></ul><h2 id="测试逻辑" tabindex="-1">测试逻辑 <a class="header-anchor" href="#测试逻辑" aria-label="Permalink to &quot;测试逻辑&quot;">​</a></h2><p>后端会使用一条标准的演示测量上下文，按当前设置执行 AI 解读流程：</p><h3 id="_1-disabled" tabindex="-1">1. <code>disabled</code> <a class="header-anchor" href="#_1-disabled" aria-label="Permalink to &quot;1. `disabled`&quot;">​</a></h3><ul><li>结果会显示不可用</li><li>不会调用外部模型</li></ul><h3 id="_2-template" tabindex="-1">2. <code>template</code> <a class="header-anchor" href="#_2-template" aria-label="Permalink to &quot;2. `template`&quot;">​</a></h3><ul><li>结果会显示可用</li><li>后端直接返回模板化中文解释</li><li>不依赖外部模型服务</li></ul><h3 id="_3-openai-compatible" tabindex="-1">3. <code>openai_compatible</code> <a class="header-anchor" href="#_3-openai-compatible" aria-label="Permalink to &quot;3. `openai_compatible`&quot;">​</a></h3><ul><li>如果模型地址和 Key 可用，会调用外部模型</li><li>如果调用失败，会自动回退模板解释</li></ul><h2 id="返回关键字段" tabindex="-1">返回关键字段 <a class="header-anchor" href="#返回关键字段" aria-label="Permalink to &quot;返回关键字段&quot;">​</a></h2><ul><li><code>ok</code></li><li><code>source</code></li><li><code>content</code></li><li><code>error</code></li><li><code>prompt</code></li><li><code>context</code></li></ul><p>其中：</p><ul><li><code>ok=true</code> 表示当前模式至少能返回有效解释</li><li><code>source=template</code> 表示当前使用模板解释</li><li><code>source=llm</code> 表示当前成功调用了外部模型</li><li><code>source=template_fallback</code> 表示原本想调用外部模型，但失败后回退到了模板</li></ul><h2 id="这对演示的意义" tabindex="-1">这对演示的意义 <a class="header-anchor" href="#这对演示的意义" aria-label="Permalink to &quot;这对演示的意义&quot;">​</a></h2><p>这个测试功能有两个用途：</p><h3 id="_1-演示稳定" tabindex="-1">1. 演示稳定 <a class="header-anchor" href="#_1-演示稳定" aria-label="Permalink to &quot;1. 演示稳定&quot;">​</a></h3><p>即使外部模型没接通，<code>template</code> 模式也能稳定展示 AI 解读能力。</p><h3 id="_2-联调清晰" tabindex="-1">2. 联调清晰 <a class="header-anchor" href="#_2-联调清晰" aria-label="Permalink to &quot;2. 联调清晰&quot;">​</a></h3><p>当你后续接入真实模型时，可以直接在页面上验证：</p><ul><li>配置是否正确</li><li>Key 是否有效</li><li>模型是否真的返回内容</li></ul><h2 id="推荐使用方式" tabindex="-1">推荐使用方式 <a class="header-anchor" href="#推荐使用方式" aria-label="Permalink to &quot;推荐使用方式&quot;">​</a></h2><p>毕设答辩或日常开发阶段，建议默认使用：</p><ul><li><code>enabled = true</code></li><li><code>mode = template</code></li></ul><p>这样最稳。</p><p>如果之后接入真实大模型，再切换到：</p><ul><li><code>mode = openai_compatible</code></li></ul><p>并通过“测试可用性”按钮验证配置是否生效。</p>',34)])])}const m=a(o,[["render",d]]);export{p as __pageData,m as default};
